window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e3a0fad3fdd561ba"]={"versions": [{"id": "FIG-e3a0fad3fdd561ba", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Kontrollflussdiagramm) mit Entscheidungsknoten (<em>Decision Node</em>), Guard-Bedingungen und Aktionszuständen (<em>Action States</em> / <code>WriteVariable</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), E2E-Transformer-Modul (<code>E2EXf</code>), Spezifikationsdokument <code>AUTOSAR_CP_SWS_E2ETransformer</code>.\n</li><li><strong>Funktionale Einordnung:</strong> Spezifikation der Nachbearbeitungsroutine (<code>post_check</code>) des inversen E2E-Transformers (<code>E2EXf_Inv_handling_PXXm</code>) auf der <strong>Server-Seite</strong> im Rahmen einer Client/Server-Kommunikation (<code>C/S: Server</code>). Die Logik sichert die Identität des anfragenden Clients sowie die Transaktionssequenz aus dem deserialisierten E2E-Header eines eingehenden Requests zur späteren Referenzierung bei der Response-Erstellung.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Rollen (gemäß Farbcodierung):</strong>\n<ul class=\"fig-list\"><li><em>Türkis / Cyan (<code>C/S: Server</code>):</em> Kennzeichnet die operative Ausführung im Kontext des Server-seitigen E2E-Invers-Transformers.\n</li><li><em>Legende <code>Communication Types</code>:</em> Unterscheidet Systemprofile und Kommunikationsmuster (<code>All types</code>, <code>Sender/Receiver</code>, <code>Publisher/Subscriber</code>, <code>C/S: Server</code>, <code>C/S: Client</code>, <code>Signal to Service</code>).\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Variablen:</strong>\n<ul class=\"fig-list\"><li><code>Profile == PXXm</code>: Evaluierung des aktivierten E2E-Profils (Sammelbezeichnung für erweiterte C/S-taugliche Profile mit Multiple-Client-Unterstützung, z. B. P04m, P05m, P06m, P07m, P08m, P11m, P22m).\n</li><li><code>csTransactionHandle</code>: Zeiger auf die vom RTE bereitgestellte Transaktions-Kontextstruktur für Client/Server-Aufrufe.\n<ul class=\"fig-list\"><li><code>csTransactionHandle-&gt;e2eSourceId</code>: Datenfeld zur Aufnahme der eindeutigen Client-Quell-ID.\n</li><li><code>csTransactionHandle-&gt;e2eCounter</code>: Datenfeld zur Aufnahme des im Request übertragenen Sequenzzählers.\n</li></ul>\n</li><li><code>sourceID</code>: Lokale Variable / Parameter mit der aus dem E2E-Header des empfangenen Request-Payloads extrahierten Client-Identifikationsnummer.\n</li><li><code>receivedRequestCounter</code>: Lokale Variable / Parameter mit dem empfangenen E2E-Nachrichtenzähler des Requests.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Eintritt:</strong> Start nach erfolgreicher Ausführung der profil-spezifischen E2E-Prüfroutine (<code>E2E_PXXmCheck()</code>).\n</li><li><strong>Profilweiche (Decision Node):</strong>\n<ul class=\"fig-list\"><li><strong>Bedingung <code>[Profile == PXXm]</code>:</strong>\n<ul class=\"fig-list\"><li><code>[FALSE]</code>: Der Transformer umgeht jegliche Zuweisung und wechselt unmittelbar zum Endknoten (<em>Activity Final Node</em>).\n</li><li><code>[TRUE]</code>: Eintritt in den sequenziellen Zuweisungspfad.\n</li></ul>\n</li></ul>\n</li><li><strong>Persistierung der Transaktionsdaten (<code>WriteVariable</code>):</strong>\n<ul class=\"fig-list\"><li>Schritt 1: <code>csTransactionHandle-&gt;e2eSourceId = sourceID;</code> speichert die Client-Source-ID im Transaktions-Handle.\n</li><li>Schritt 2: <code>csTransactionHandle-&gt;e2eCounter = receivedRequestCounter;</code> sichert den Request-Counter im selben Handle.\n</li></ul>\n</li><li><strong>Terminierung:</strong> Übergang in den Endknoten. Die Transaktionsdaten stehen der Server-RTE und nachfolgenden Schritten der Transformer-Kette zur Verfügung.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normativer Bezug:</strong>\n<ul class=\"fig-list\"><li><code>RS_E2E_08538</code>: Anforderung zur Unterstützung von E2E-gesicherter Client/Server-Kommunikation mit mehreren parallelen Clients.\n</li><li><code>SWS_E2EXf_00202</code>: Verpflichtendes Schreiben der <code>sourceID</code> in das <code>csTransactionHandle</code> bei <code>PXXm</code>-Profilen im Server-Invers-Transformer.\n</li><li><code>SWS_E2EXf_00203</code>: Verpflichtendes Schreiben des <code>receivedRequestCounter</code> in das <code>csTransactionHandle</code>.\n</li></ul>\n</li><li><strong>Stack- &amp; RTE-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Das <code>csTransactionHandle</code> muss von der RTE instanziiert, über den Aufrufkontext an <code>E2EXf_Inv_&lt;TransformerId&gt;</code> übergeben und über die gesamte Ausführungsdauer der Server-Operation bis zum Aufruf des vorwärtsgerichteten Transformers (<code>E2EXf_&lt;TransformerId&gt;</code>) für die Response vorgehalten werden.\n</li><li>Bei Response-Generierung dient <code>csTransactionHandle-&gt;e2eSourceId</code> der Adressierung bzw. Profilvalidierung und <code>csTransactionHandle-&gt;e2eCounter</code> zur Rekonstruktion des korrekten E2E-Schutzes (Request-Response-Pairing / Counter-Spiegelung zur Erkennung vertauschter oder verspäteter Antworten).\n</li></ul>\n</li><li><strong>Konfigurations-Einschränkungen:</strong>\n<ul class=\"fig-list\"><li>Ist kein <code>PXXm</code>-Profil konfiguriert (sondern Standardprofile wie P01–P07 ohne &#x27;m&#x27;), entfällt diese Zuweisung; ein C/S-Server-Betrieb mit mehreren Clients über denselben Kommunikationspfad ist dann normativ nicht E2E-abgesichert möglich.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ca034547011d3857", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Kontrollflussdiagramm) mit Entscheidungsknoten (<em>Decision Node</em>), Guard-Bedingungen und Aktionszuständen (<em>Action States</em> / <code>WriteVariable</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), E2E-Transformer-Modul (<code>E2EXf</code>), Spezifikationsdokument <code>AUTOSAR_CP_SWS_E2ETransformer</code>.\n</li><li><strong>Funktionale Einordnung:</strong> Spezifikation der Nachbearbeitungsroutine (<code>post_check</code>) des inversen E2E-Transformers (<code>E2EXf_Inv_handling_PXXm</code>) auf der <strong>Server-Seite</strong> im Rahmen einer Client/Server-Kommunikation (<code>C/S: Server</code>). Die Logik sichert die Identität des anfragenden Clients sowie die Transaktionssequenz aus dem deserialisierten E2E-Header eines eingehenden Requests zur späteren Referenzierung bei der Response-Erstellung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Rollen (gemäß Farbcodierung):</strong>\n<ul class=\"fig-list\"><li><em>Türkis / Cyan (<code>C/S: Server</code>):</em> Kennzeichnet die operative Ausführung im Kontext des Server-seitigen E2E-Invers-Transformers.\n</li><li><em>Legende <code>Legend</code>:</em> Unterscheidet Systemprofile und Kommunikationsmuster (<code>All types</code>, <code>Sender/Receiver</code>, <code>Publisher/Subscriber</code>, <code>C/S: Server</code>, <code>C/S: Client</code>, <code>Signal to Service</code>).\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Variablen:</strong>\n<ul class=\"fig-list\"><li><code>Profile == PXXm</code>: Evaluierung des aktivierten E2E-Profils (Sammelbezeichnung für erweiterte C/S-taugliche Profile mit Multiple-Client-Unterstützung, z. B. P04m, P05m, P06m, P07m, P08m, P11m, P22m).\n</li><li><code>csTransactionHandle</code>: Zeiger auf die vom RTE bereitgestellte Transaktions-Kontextstruktur für Client/Server-Aufrufe.\n<ul class=\"fig-list\"><li><code>csTransactionHandle-&gt;e2eSourceId</code>: Datenfeld zur Aufnahme der eindeutigen Client-Quell-ID.\n</li><li><code>csTransactionHandle-&gt;e2eCounter</code>: Datenfeld zur Aufnahme des im Request übertragenen Sequenzzählers.\n</li></ul>\n</li><li><code>sourceID</code>: Lokale Variable / Parameter mit der aus dem E2E-Header des empfangenen Request-Payloads extrahierten Client-Identifikationsnummer.\n</li><li><code>receivedRequestCounter</code>: Lokale Variable / Parameter mit dem empfangenen E2E-Nachrichtenzähler des Requests.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Eintritt:</strong> Start nach erfolgreicher Ausführung der profil-spezifischen E2E-Prüfroutine (<code>E2E_PXXmCheck()</code>).\n</li><li><strong>Profilweiche (Decision Node):</strong>\n<ul class=\"fig-list\"><li><strong>Bedingung <code>[Profile == PXXm]</code>:</strong>\n<ul class=\"fig-list\"><li><code>[FALSE]</code>: Der Transformer umgeht jegliche Zuweisung und wechselt unmittelbar zum Endknoten (<em>Activity Final Node</em>).\n</li><li><code>[TRUE]</code>: Eintritt in den sequenziellen Zuweisungspfad.\n</li></ul>\n</li></ul>\n</li><li><strong>Persistierung der Transaktionsdaten (<code>WriteVariable</code>):</strong>\n<ul class=\"fig-list\"><li>Schritt 1: <code>csTransactionHandle-&gt;e2eSourceId = sourceID;</code> speichert die Client-Source-ID im Transaktions-Handle.\n</li><li>Schritt 2: <code>csTransactionHandle-&gt;e2eCounter = receivedRequestCounter;</code> sichert den Request-Counter im selben Handle.\n</li></ul>\n</li><li><strong>Terminierung:</strong> Übergang in den Endknoten. Die Transaktionsdaten stehen der Server-RTE und nachfolgenden Schritten der Transformer-Kette zur Verfügung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normativer Bezug:</strong>\n<ul class=\"fig-list\"><li><code>RS_E2E_08538</code>: Anforderung zur Unterstützung von E2E-gesicherter Client/Server-Kommunikation mit mehreren parallelen Clients.\n</li><li><code>SWS_E2EXf_00202</code>: Verpflichtendes Schreiben der <code>sourceID</code> in das <code>csTransactionHandle</code> bei <code>PXXm</code>-Profilen im Server-Invers-Transformer.\n</li><li><code>SWS_E2EXf_00203</code>: Verpflichtendes Schreiben des <code>receivedRequestCounter</code> in das <code>csTransactionHandle</code>.\n</li></ul>\n</li><li><strong>Stack- &amp; RTE-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Das <code>csTransactionHandle</code> muss von der RTE instanziiert, über den Aufrufkontext an <code>E2EXf_Inv_&lt;TransformerId&gt;</code> übergeben und über die gesamte Ausführungsdauer der Server-Operation bis zum Aufruf des vorwärtsgerichteten Transformers (<code>E2EXf_&lt;TransformerId&gt;</code>) für die Response vorgehalten werden.\n</li><li>Bei Response-Generierung dient <code>csTransactionHandle-&gt;e2eSourceId</code> der Adressierung bzw. Profilvalidierung und <code>csTransactionHandle-&gt;e2eCounter</code> zur Rekonstruktion des korrekten E2E-Schutzes (Request-Response-Pairing / Counter-Spiegelung zur Erkennung vertauschter oder verspäteter Antworten).\n</li></ul>\n</li><li><strong>Konfigurations-Einschränkungen:</strong>\n<ul class=\"fig-list\"><li>Ist kein <code>PXXm</code>-Profil konfiguriert (sondern Standardprofile wie P01–P07 ohne &#x27;m&#x27;), entfällt diese Zuweisung; ein C/S-Server-Betrieb mit mehreren Clients über denselben Kommunikationspfad ist dann normativ nicht E2E-abgesichert möglich.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e3a0fad3fdd561ba", "to": "FIG-ca034547011d3857", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Legende:</strong> Titel des Legendenkastens von „Communication Types“ in „Legend“ umbenannt.\n</li></ul>"}]};
